const {DatabaseSync}=require("node:sqlite");
const db=new DatabaseSync(".codegraph/codegraph.db");
function callersOf(name, fp){
  const n=db.prepare("SELECT id FROM nodes WHERE name=? AND file_path=? AND kind IN ('function','method')").get(name,fp);
  const rows=db.prepare("SELECT DISTINCT s.file_path AS fp FROM edges e JOIN nodes s ON s.id=e.source WHERE e.target=? AND e.kind='calls'").all(n.id);
  console.log(name+" ("+fp+") distinct caller files: "+rows.length);
  for (const r of rows.slice(0,20)) console.log("  "+r.fp);
}
callersOf("Len","internal/version/version.go");
console.log("---");
callersOf("Next","internal/scheduler/parser.go");
EOF
